mod polynomial_peaks{
use super::*;
#[derive(Clone,Copy,Debug)]struct Term{a:usize,b:usize,kind:K,g:u32,producer:usize,function:u32}
#[derive(Clone,Debug)]struct Candidate{wire:usize,terms:Vec<Term>}
struct Region{lo:usize,max_need:usize,candidates:Vec<Candidate>,touches:HashSet<usize>}
fn eval_terms(e:&mut Expr,terms:&[Term],q:&[u32])->u32{let mut sum=0;for t in terms{let v=match t.kind{K::X=>t.g,K::CX=>e.and(t.g,q[t.a]),K::CCX=>{let p=e.and(q[t.a],q[t.b]);e.and(t.g,p)},_=>unreachable!()};sum=e.xor(sum,v);}sum}
fn controls(c:&Candidate)->HashSet<usize>{let mut out=HashSet::new();for t in &c.terms{if t.kind!=K::X{out.insert(t.a);}if t.kind==K::CCX{out.insert(t.b);}}out}
fn compatible(a:&Candidate,b:&Candidate)->bool{!controls(a).contains(&b.wire)&&!controls(b).contains(&a.wire)}
pub(super)fn run(ops:&[Op],cap:usize,limit:usize)->serde_json::Value{
 let no=u64::MAX;let(nq,nb,_,_)=quantum_ecc::circuit::analyze_ops(ops.iter());let(nq,nb)=(nq as usize,nb as usize);assert!(cap<nq&&limit>0);let mut alg=Algebra{inner:Expr::default()};let(mut q,mut c)=initial_inputs(ops,nq,nb,&mut alg);let pinned:HashSet<_>=ops.iter().filter(|o|o.kind==K::AppendToRegister&&o.q_target.0!=no).map(|o|o.q_target.0 as usize).collect();let mut active:Vec<_>=(0..nq).map(|j|pinned.contains(&j)).collect();let mut recipes:Vec<Option<Vec<Term>>>=(0..nq).map(|j|if pinned.contains(&j){None}else{Some(vec![])}).collect();let mut live=pinned.len();let(mut base,mut stack)=(1,vec![]);let mut region:Option<Region>=None;let(mut ccx,mut clifford,mut failed,mut peak)=(0usize,0usize,0usize,live);let mut rows=vec![];let mut truncated=0usize;
 for(i,o)in ops.iter().enumerate(){if o.kind==K::PushCondition{stack.push(base);base=alg.inner.and(base,c[o.c_condition.0 as usize]);continue;}if o.kind==K::PopCondition{base=stack.pop().unwrap();continue;}let g=if o.c_condition.0==no{base}else{alg.inner.and(base,c[o.c_condition.0 as usize])};let(t,a,b,ct)=(o.q_target.0 as usize,o.q_control1.0 as usize,o.q_control2.0 as usize,o.c_target.0 as usize);let mut used:Vec<_>=[o.q_control2.0,o.q_control1.0,o.q_target.0].into_iter().filter(|&j|j!=no).map(|j|j as usize).collect();used.sort_unstable();used.dedup();let need=live+used.iter().filter(|&&j|!active[j]).count();peak=peak.max(need);
  if need>cap&&region.is_none(){let mut candidates=vec![];for wire in 0..nq{if pinned.contains(&wire)||!active[wire]||q[wire]==0{continue;}let Some(terms)=&recipes[wire]else{continue;};let candidate=Candidate{wire,terms:terms.clone()};if candidate.terms.is_empty()||controls(&candidate).contains(&wire){continue;}if eval_terms(&mut alg.inner,&candidate.terms,&q)==q[wire]{candidates.push(candidate);}}region=Some(Region{lo:i,max_need:need,candidates,touches:HashSet::new()});}
  if let Some(r)=&mut region{r.max_need=r.max_need.max(need);r.touches.extend(used.iter().copied());}for &j in &used{if !active[j]{active[j]=true;live+=1;}}
  let toggle=match o.kind{K::X=>Some(g),K::CX=>Some(alg.inner.and(q[a],g)),K::CCX=>{let p=alg.inner.and(q[a],q[b]);Some(alg.inner.and(g,p))},_=>None};
  if let Some(function)=toggle{if !pinned.contains(&t){if q[t]==0{recipes[t]=Some(vec![]);}if function!=0{if let Some(terms)=&mut recipes[t]{if let Some(position)=terms.iter().position(|term|term.function==function){terms.remove(position);}else if terms.len()<limit{terms.push(Term{a,b,kind:o.kind,g,producer:i,function});}else{recipes[t]=None;truncated+=1;}}}}}
  match o.kind{K::X|K::CX|K::CCX=>q[t]=alg.inner.xor(q[t],toggle.unwrap()),K::Swap=>{let v=alg.inner.xor(q[a],q[t]);let v=alg.inner.and(g,v);q[a]=alg.inner.xor(q[a],v);q[t]=alg.inner.xor(q[t],v);if g==1{recipes.swap(a,t);}else if g!=0{recipes[a]=None;recipes[t]=None;}},K::R|K::Hmr=>{q[t]=alg.inner.and(q[t],g^1);recipes[t]=None;if o.kind==K::Hmr{let r=alg.inner.atom();c[ct]=alg.inner.ite(g,r,c[ct]);}},K::BitInvert=>c[ct]=alg.inner.xor(c[ct],g),K::BitStore0=>c[ct]=alg.inner.and(c[ct],g^1),K::BitStore1=>c[ct]=alg.inner.or(c[ct],g),K::Neg|K::Z|K::CZ|K::CCZ|K::Register|K::AppendToRegister|K::DebugPrint=>{},_=>unreachable!()}
  for &j in &used{if !pinned.contains(&j)&&q[j]==0{assert!(active[j]);active[j]=false;live-=1;recipes[j]=Some(vec![]);}}
  if live<=cap{if let Some(r)=region.take(){let mut good:Vec<_>=r.candidates.iter().filter(|candidate|!r.touches.contains(&candidate.wire)&&eval_terms(&mut alg.inner,&candidate.terms,&q)==q[candidate.wire]).cloned().collect();good.sort_by_key(|candidate|(candidate.terms.iter().filter(|t|t.kind==K::CCX).count(),candidate.terms.len(),candidate.wire));let n_good=good.len();let needed=r.max_need-cap;let mut selected:Vec<Candidate>=vec![];for candidate in good{if selected.iter().all(|old|compatible(old,&candidate)){selected.push(candidate);if selected.len()==needed{break;}}}
   if selected.len()==needed{let mut added_ccx=0;let mut added_clifford=0;let victims:Vec<_>=selected.iter().map(|candidate|{let terms:Vec<_>=candidate.terms.iter().map(|t|{if t.kind==K::CCX{added_ccx+=2;}else{added_clifford+=2;}serde_json::json!({"a":t.a,"b":t.b,"kind":t.kind as u32,"guard_expression":t.g,"producer":t.producer,"original_toggle_function":t.function})}).collect();serde_json::json!({"wire":candidate.wire,"terms":terms})}).collect();ccx+=added_ccx;clifford+=added_clifford;rows.push(serde_json::json!({"lo":r.lo,"hi":i,"needed":needed,"victims":victims,"status":"COMPLETE_EXACT_POLYNOMIAL_VICTIM_SET","extra_toffoli_records_upper_bound":added_ccx,"extra_non_toffoli_recipe_gates":added_clifford}));}
   else{failed+=1;rows.push(serde_json::json!({"lo":r.lo,"hi":i,"needed":needed,"initial_recipe_candidates":r.candidates.len(),"surviving_exact_recipe_candidates":n_good,"independent_available":selected.len(),"status":"UNPROVED_INSUFFICIENT_EXACT_POLYNOMIAL_RECIPES"}));}}}
  if i%1000000==0{eprintln!("POLY_PEAK op={i} cap={cap} regions={} failed={failed} added_ccx_records={ccx} nodes={}",rows.len(),alg.inner.nodes.len());}
 }
 assert!(stack.is_empty());let complete=failed==0&&region.is_none();serde_json::json!({"status":"READ_ONLY_POLYNOMIAL_REMATERIALIZATION_NOT_AN_EMITTED_CIRCUIT_OR_SCORE","original_qubits":nq,"target_cap":cap,"term_limit":limit,"original_lifetime_peak":peak,"all_regions_covered":complete,"unproved_regions":failed,"unfinished_final_region":region.is_some(),"extra_executed_toffoli_per_shot_upper_bound":if complete{Some(ccx)}else{None},"extra_non_toffoli_recipe_gates":clifford,"recipe_budget_forgets":truncated,"regions":rows,"input_records_sha3":hash(ops),"semantic_nodes":alg.inner.nodes.len(),"scope":"Each helper recipe is an XOR of bounded original guarded X/CX/CCX accumulator updates since provedzero; equal original toggle functions cancel exactly. Current entire XOR must equal helper both before/after region. Helpers untouched; selected victims mutually independent. Historical guards require exact capture at producers and flattened scopes. No new RNG. Partial plans never have a complete resource bound; no circuit/achieved width/point input/gate/nonce/benchmark."})
}
#[cfg(test)]mod tests{use super::*;
 fn metadata()->Vec<Op>{let mut v:Vec<_>=(0..4).map(|q|{let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=quantum_ecc::circuit::RegisterId(0);o.q_target=QubitId(q);o}).collect();let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=quantum_ecc::circuit::RegisterId(1);o.c_target=BitId(0);v.push(o);v}
 fn fixture()->Vec<Op>{let n=u64::MAX;let mut v=metadata();v.extend([make(K::CCX,0,1,4,n,0),make(K::CX,n,2,4,n,n),make(K::CX,n,0,5,n,n),make(K::BitInvert,n,n,n,0,n),make(K::R,n,n,5,n,n),make(K::CX,n,4,3,n,n),make(K::R,n,n,4,n,n)]);v}
 #[test]fn xor_accumulator_recipe_covers_a_peak_that_needs_multiple_terms(){let s=run(&fixture(),5,8);assert_eq!(s["all_regions_covered"],true);assert_eq!(s["regions"][0]["victims"][0]["terms"].as_array().unwrap().len(),2);assert_eq!(s["extra_executed_toffoli_per_shot_upper_bound"],2);let s=run(&fixture(),5,1);assert_eq!(s["all_regions_covered"],false);assert!(s["extra_executed_toffoli_per_shot_upper_bound"].is_null());}
 #[test]fn historical_guard_polynomial_uncompute_restore_preserves_full_protected_phase_rng_and_values(){use quantum_ecc::sim::Simulator;use sha3::digest::XofReader;struct W{word:u64,at:usize}impl XofReader for W{fn read(&mut self,b:&mut[u8]){b.copy_from_slice(&self.word.rotate_left(self.at as u32).to_le_bytes());self.at+=1;}}let n=u64::MAX;let ops=fixture();let p=run(&ops,5,8);let r=&p["regions"][0];let(lo,hi)=(r["lo"].as_u64().unwrap()as usize,r["hi"].as_u64().unwrap()as usize);let terms=r["victims"][0]["terms"].as_array().unwrap();let mut inserts=vec![];let mut capture=HashMap::new();for(index,t)in terms.iter().enumerate(){let at=t["producer"].as_u64().unwrap()as usize;let bit=index as u64+1;capture.insert(at,bit);let mut o=ops[at];o.c_condition=BitId(bit);inserts.push(o);}let mut out=vec![];for(i,&o)in ops.iter().enumerate(){if let Some(&bit)=capture.get(&i){out.push(make(K::BitStore0,n,n,n,bit,n));if o.c_condition.0==n{out.push(make(K::BitStore1,n,n,n,bit,n));}else{out.push(make(K::BitStore1,n,n,n,bit,o.c_condition.0));}}if i==lo{out.extend_from_slice(&inserts);}out.push(o);if i==hi{out.extend_from_slice(&inserts);}}for word in[0,u64::MAX,0xa55a_dd33_1188_ee01]{let(mut ra,mut rb)=(W{word,at:0},W{word,at:0});let(mut a,mut b)=(Simulator::new(6,3,&mut ra),Simulator::new(6,3,&mut rb));for lane in 0..64{for q in 0..4{a.qubits[q]|=((lane>>q&1)as u64)<<lane;}a.bits[0]|=((lane>>4&1)as u64)<<lane;}b.qubits.clone_from(&a.qubits);b.bits.clone_from(&a.bits);let g=a.bits[0];a.apply_iter(ops.iter());b.apply_iter(out.iter());assert_eq!(a.qubits,b.qubits);assert_eq!(a.phase,b.phase);assert_eq!(a.bits[0],b.bits[0]);assert_eq!(b.stats.toffoli_gates-a.stats.toffoli_gates,2*g.count_ones()as u64);drop((a,b));assert_eq!(ra.at,rb.at);}}
 #[test]fn changed_control_without_restored_polynomial_and_cross_victim_dependencies_fail(){let n=u64::MAX;let mut ops=fixture();ops.insert(9,make(K::X,n,n,2,n,n));let s=run(&ops,5,8);assert_eq!(s["all_regions_covered"],false);let a=Candidate{wire:4,terms:vec![Term{a:5,b:0,kind:K::CX,g:1,producer:0,function:2}]};let b=Candidate{wire:5,terms:vec![Term{a:0,b:0,kind:K::CX,g:1,producer:1,function:4}]};assert!(!compatible(&a,&b));}
}
}
